import os
from identity_client import CognitoClient
from identity_models import UserLoginRequest, AuthResponse, AuthChallengeResponse


def email_password_login(payload: UserLoginRequest, config=None) -> AuthResponse:
    config = config or {}
    cognito_client = CognitoClient(
        region_name=config.get("region"),
        client_id=config.get("client_id"),
        client_secret=config.get("client_secret")
    )

    secret_hash = cognito_client._get_secret_hash(payload.email)

    auth_params = {
        "USERNAME": payload.email,
        "PASSWORD": payload.password,
    }
    if secret_hash:
        auth_params["SECRET_HASH"] = secret_hash

    response = cognito_client.client.initiate_auth(
        ClientId=cognito_client.client_id,
        AuthFlow='USER_PASSWORD_AUTH',
        AuthParameters=auth_params
    )

    if 'ChallengeName' in response:
        return AuthResponse(
            challenge=AuthChallengeResponse(
                challenge_name=response['ChallengeName'],
                session=response['Session'],\                challenge_parameters=response.get('ChallengeParameters', {})
            )
        )
    elif 'AuthenticationResult' in response:
        auth_result = response['AuthenticationResult']
        return AuthResponse(
            access_token=auth_result.get('AccessToken'),
            id_token=auth_result.get('IdToken'),
            refresh_token=auth_result.get('RefreshToken'),
            expires_in=auth_result.get('ExpiresIn'),
            token_type=auth_result.get('TokenType'),
            user_confirmed=True # Assuming user is confirmed if auth result is present
        )
    return AuthResponse(user_confirmed=False)

import os
from identity_client import CognitoClient
from identity_models import RefreshSessionRequest, AuthResponse


def refresh_session(payload: RefreshSessionRequest, config=None) -> AuthResponse:
    config = config or {}
    cognito_client = CognitoClient(
        region_name=config.get("region"),
        client_id=config.get("client_id"),
        client_secret=config.get("client_secret")
    )

    auth_params = {
        "REFRESH_TOKEN": payload.refresh_token,
    }
    # No SecretHash needed for refresh_token flow

    response = cognito_client.client.initiate_auth(
        ClientId=cognito_client.client_id,
        AuthFlow='REFRESH_TOKEN_AUTH',
        AuthParameters=auth_params
    )

    if 'AuthenticationResult' in response:
        auth_result = response['AuthenticationResult']
        return AuthResponse(
            access_token=auth_result.get('AccessToken'),
            id_token=auth_result.get('IdToken'),
            refresh_token=payload.refresh_token, # Refresh token is usually not returned again
            expires_in=auth_result.get('ExpiresIn'),
            token_type=auth_result.get('TokenType')
        )
    return AuthResponse()

import os
from identity_client import CognitoClient
from identity_models import PasswordResetRequest


def password_reset(payload: PasswordResetRequest, config=None) -> dict:
    config = config or {}
    cognito_client = CognitoClient(
        region_name=config.get("region"),
        client_id=config.get("client_id"),
        client_secret=config.get("client_secret")
    )

    # For password reset, we first need to forgot password
    # Cognito will send a confirmation code to the user's email
    try:
        response = cognito_client.client.forgot_password(
            ClientId=cognito_client.client_id,
            Username=payload.email,
            SecretHash=cognito_client._get_secret_hash(payload.email) # SecretHash is needed if client has one
        )
        return {"status": "PASSWORD_RESET_INITIATED", "code_delivery_details": response.get('CodeDeliveryDetails')}
    except cognito_client.client.exceptions.UserNotFoundException:
        return {"status": "USER_NOT_FOUND", "message": "User not found."}
    except Exception as e:
        return {"status": "ERROR", "message": str(e)}

import os
from google.cloud import firestore


def profile_note_store(user_id: str, notes: str, metadata: dict, config=None) -> dict:
    config = config or {}
    # Google Cloud Firestore automatically uses GOOGLE_APPLICATION_CREDENTIALS
    # or other standard authentication methods.
    db = firestore.Client(
        project=config.get("gcp_project_id") or os.environ.get("GCP_PROJECT_ID")
    )

    # Reference to the user's document in a 'onboarding_notes' collection
    doc_ref = db.collection('onboarding_notes').document(user_id)

    # Data to be stored
    data = {
        'notes': notes,
        'metadata': metadata,
        'timestamp': firestore.SERVER_TIMESTAMP
    }

    # Set the data in the document. This will create or overwrite the document.
    doc_ref.set(data)

    return {"status": "success", "user_id": user_id, "doc_path": doc_ref.path}
